# ----------------------------------------------------------------------------- assets
def _first_existing(paths):
    return next((p for p in paths if p.exists()), None)


@st.cache_resource
def font_path() -> Path | None:
    """Find the Space Grotesk .ttf next to app.py (or in static/ assets/ ola_intro/)."""
    for folder in (ROOT, ROOT / "static", ROOT / "assets", INTRO_DIR):
        if folder.is_dir():
            for p in sorted(folder.glob("*.ttf")):
                if "space" in p.name.lower() and "grotesk" in p.name.lower():
                    return p
    return None


def font_b64() -> str:
    return FONT_B64


def prepare_intro() -> dict:
    """Create ola_intro/ (index.html + SpaceGrotesk.ttf). The intro is an animated scene drawn in code, no video file needed."""
    INTRO_DIR.mkdir(exist_ok=True)
    (INTRO_DIR / INTRO_FONT).write_bytes(base64.b64decode(FONT_B64))
    (INTRO_DIR / "index.html").write_text(INTRO_HTML.replace("__CUR__", CURSOR_URL), encoding="utf-8")
    return {"font": True}


