def inject_js(js: str, tag: str) -> None:
    boot = ("<script>(function(){try{var d=window.parent.document;if(d.getElementById('%s'))return;"
            "var s=d.createElement('script');s.id='%s';s.textContent=%s;d.head.appendChild(s);}catch(e){}})();</script>" % (tag, tag, json.dumps(js)))
