# ----------------------------------------------------------------------------- shared helpers (unchanged 3D builders included)
def fmt_in(n: float) -> str:
    n = int(round(n))
    s = str(abs(n))
    if len(s) > 3:
        head, tail, parts = s[:-3], s[-3:], []
        while len(head) > 2:
            parts.insert(0, head[-2:])
            head = head[:-2]
        if head:
            parts.insert(0, head)
        s = ",".join(parts + [tail])
    return ("-" if n < 0 else "") + s


def short_in(v: float) -> tuple[str, float, int, str]:
    if abs(v) >= 1e7:
        return f"{v / 1e7:.2f} Cr", v / 1e7, 2, " Cr"
    if abs(v) >= 1e5:
        return f"{v / 1e5:.2f} L", v / 1e5, 2, " L"
    return fmt_in(v), v, 0, ""


def mode_of(s: pd.Series) -> str:
    s = s.dropna()
    return str(s.mode().iloc[0]) if len(s) else "-"


def hex_rgba(h: str, a: float) -> str:
    h = h.lstrip("#")
    return f"rgba({int(h[0:2], 16)},{int(h[2:4], 16)},{int(h[4:6], 16)},{a})"


def plot(fig: go.Figure, key: str, select: bool = False):
    kw = dict(config={"displayModeBar": False, "responsive": True}, key=key)
    if select:
        kw.update(on_select="rerun", selection_mode="points")
    try:
        return st.plotly_chart(fig, use_container_width=True, **kw)
    except TypeError:
        return st.plotly_chart(fig, width="stretch", **kw)


def html_table(d: pd.DataFrame, bars: dict | None = None, max_rows: int = 200) -> str:
    bars = bars or {}
    head = "".join(f"<th>{html.escape(str(c))}</th>" for c in d.columns)
    rows = []
    for _, r in d.head(max_rows).iterrows():
        tds = []
        for c in d.columns:
            v = r[c]
            txt = "" if (not isinstance(v, (list, dict)) and pd.isna(v)) else (f"{v:,.2f}" if isinstance(v, (float, np.floating)) else str(v))
            if c in bars and txt != "":
                mx, col = bars[c]
                w = 0 if not mx else max(0, min(100, float(v) / mx * 100))
                tds.append(f'<td><div class="pb"><i style="width:{w:.0f}%;background:{col}"></i><span>{html.escape(txt)}</span></div></td>')
            else:
                tds.append(f"<td>{html.escape(txt)}</td>")
        rows.append("<tr>" + "".join(tds) + "</tr>")
    return f'<div class="tbl"><table><thead><tr>{head}</tr></thead><tbody>{"".join(rows)}</tbody></table></div>'


def style(fig: go.Figure, h: int = 320, title: str | None = None, legend: bool = False) -> go.Figure:
    fig.update_layout(
        template="plotly_dark", paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family=FONT_STACK, color=INK, size=12), height=h, colorway=COLORWAY,
        margin=dict(l=10, r=10, t=48 if title else 14, b=10), showlegend=legend,
        title=dict(text=title.upper(), x=0.02, xanchor="left", font=dict(family=FONT_STACK, size=13, color=INK)) if title else None,
        legend=dict(orientation="h", y=-0.14, font=dict(size=11)),
        hoverlabel=dict(bgcolor="#11151D", bordercolor=LIME, font=dict(family=FONT_STACK, color=INK, size=13)))
    fig.update_xaxes(gridcolor="rgba(255,255,255,.05)", zeroline=False, linecolor="rgba(255,255,255,.1)")
    fig.update_yaxes(gridcolor="rgba(255,255,255,.05)", zeroline=False, linecolor="rgba(255,255,255,.1)")
    return fig


def scene(xt: str, yt: str, zt: str, aspect=None) -> dict:
    ax = dict(backgroundcolor="rgba(0,0,0,0)", gridcolor="rgba(255,255,255,.09)", showbackground=False,
              zerolinecolor="rgba(255,255,255,.15)", color=MUTE)
    s = dict(xaxis=dict(title=xt, **ax), yaxis=dict(title=yt, **ax), zaxis=dict(title=zt, **ax),
             camera=dict(eye=dict(x=1.7, y=1.7, z=0.9)), bgcolor="rgba(0,0,0,0)")
    if aspect:
        s["aspectmode"] = "manual"
        s["aspectratio"] = dict(x=aspect[0], y=aspect[1], z=aspect[2])
    return s


def html_frame(markup: str, height: int) -> None:
    """Render a small HTML page. Newer Streamlit replaced components.html with st.iframe; support both."""
    if hasattr(st, "iframe"):
        st.iframe(markup, height=max(1, height))
    else:
        components.html(markup, height=height)


