def peak_text(z: pd.DataFrame, x: str, y: str, label: str, unit: str = "", xf=None, yf="{:,.0f}") -> str:
    z = z[[x, y]].dropna()
    if z.empty:
        return "No records match the current filters."
    row = z.loc[z[y].idxmax()]
    avg = z[y].mean()
    pct = (row[y] / avg - 1) * 100 if avg else 0
    xs = xf(row[x]) if xf else str(row[x])
    return f"The strongest point is <b>{xs}</b> at <b>{yf.format(row[y])}{unit}</b> {label}, about <b>{pct:.0f}% above</b> the selection average."


def corr_text(df: pd.DataFrame, x: str, y: str, xl: str, yl: str) -> str:
    z = df[[x, y]].replace([np.inf, -np.inf], np.nan).dropna()
    if len(z) < 3 or z[x].nunique() < 2 or z[y].nunique() < 2:
        return "Not enough variation in the current filter to describe this relationship."
    r = z[x].corr(z[y])
    strength = "strong" if abs(r) >= .7 else "moderate" if abs(r) >= .4 else "weak" if abs(r) >= .2 else "very weak"
    med = z[x].median()
    delta = z.loc[z[x] > med, y].mean() - z.loc[z[x] <= med, y].mean()
    return (f"A <b>{strength} {'positive' if r > 0 else 'negative'} relationship</b> (r = {r:.2f}). Rides above the median {xl.lower()} "
            f"average <b>{abs(delta):,.1f} {'more' if delta >= 0 else 'less'} {yl.lower()}</b> than the rest.")


def chart(fig: go.Figure, key: str, rtitle: str, rtext: str) -> None:
    with st.container(border=True):
        plot(fig, key)
    readout(rtitle, rtext)


# ----------------------------------------------------------------------------- clean chart builders
def ramp(n: int) -> list[str]:
    pal = ["#00C888", "#7CF2CC", "#EEF6F3", "#02805D", "#01674E", "#5E7A72", "#0B3A2E"]
    return [pal[i % len(pal)] for i in range(n)]


def base_layout(fig: go.Figure, title: str, h: int = 390, legend: bool = False) -> go.Figure:
    fig.update_layout(height=h, margin=dict(l=20, r=20, t=55, b=30), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      font=dict(color=WHITE, family=FONT_STACK, size=13), hoverlabel=dict(bgcolor="#0A1612", font_color=WHITE, font_family=FONT_STACK),
                      showlegend=legend, legend=dict(orientation="h", y=1.12, x=0),
                      title=dict(text=title.upper(), x=0.01, xanchor="left", font=dict(size=14, family=FONT_STACK, color=WHITE)))
    fig.update_xaxes(gridcolor=GRID, zeroline=False, linecolor=GRID, tickfont=dict(color=MUTED, size=12))
    fig.update_yaxes(gridcolor=GRID, zeroline=False, linecolor=GRID, tickfont=dict(color=MUTED, size=12))
    return fig


def pulse_chart(z: pd.DataFrame, x: str, y: str, title: str, ytitle: str = "") -> go.Figure:
    z = z[[x, y]].dropna().copy()
    fig = go.Figure()
    roll = z[y].rolling(max(3, min(7, len(z))), min_periods=1, center=True).mean()
    fig.add_trace(go.Scatter(x=z[x], y=z[y], mode="lines", line=dict(color="rgba(0,200,136,.32)", width=1), fill="tozeroy",
                             fillcolor="rgba(0,200,136,.04)", hovertemplate="%{x}<br><b>%{y:,.1f}</b><extra></extra>"))
    fig.add_trace(go.Scatter(x=z[x], y=roll, mode="lines", line=dict(color=LIME, width=4, shape="spline"),
                             hovertemplate="Smoothed<br>%{x}<br><b>%{y:,.1f}</b><extra></extra>"))
    top = z.nlargest(min(3, len(z)), y)
    fig.add_trace(go.Scatter(x=top[x], y=top[y], mode="markers", marker=dict(size=10, color=WHITE, line=dict(color=LIME, width=3)),
                             hovertemplate="Peak<br>%{x}<br><b>%{y:,.1f}</b><extra></extra>"))
    fig.update_yaxes(title=ytitle)
    return base_layout(fig, title)


def neon_peak_chart(z: pd.DataFrame, x: str, y: str, title: str, ytitle: str = "") -> go.Figure:
    z = z[[x, y]].dropna().copy()
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=z[x], y=z[y], mode="lines", line=dict(color="#5E7A72", width=1), hoverinfo="skip"))
    fig.add_trace(go.Scatter(x=z[x], y=z[y], mode="markers", marker=dict(size=9, color=z[y], colorscale=[[0, "#04201A"], [0.55, "#14D69C"], [1, "#5CF2C0"]],
                                                                       showscale=False, line=dict(color=LIME, width=.4)),
                             hovertemplate="%{x}<br><b>%{y:,.1f}</b><extra></extra>"))
    if len(z):
        pk = z.loc[z[y].idxmax()]
        fig.add_trace(go.Scatter(x=[pk[x]], y=[pk[y]], mode="markers+text", text=[f"PEAK {pk[y]:,.0f}"], textposition="top center",
                                 textfont=dict(size=12), marker=dict(size=16, color=LIME, line=dict(color=WHITE, width=2)), hoverinfo="skip"))
    fig.update_yaxes(title=ytitle)
    return base_layout(fig, title)


def composition_chart(labels, values, title: str, colors=None) -> go.Figure:
    vals = np.array(values, dtype=float)
    pct = vals / vals.sum() * 100 if vals.sum() else vals
    order = np.argsort(pct)
    labels, pct = np.array(labels)[order], pct[order]
    cols = [colors[i] for i in order] if colors else ramp(len(pct))[::-1]
    fig = go.Figure(go.Bar(x=pct, y=labels, orientation="h", marker=dict(color=cols), text=[f"{v:.1f}%" for v in pct], textposition="outside",
                           textfont=dict(size=12, color=WHITE), cliponaxis=False, hovertemplate="%{y}<br><b>%{x:.1f}%</b><extra></extra>"))
    fig.update_xaxes(title="Share", range=[0, max(100, float(pct.max()) * 1.18)] if len(pct) else None)
    return base_layout(fig, title)


def donut(labels, values, title: str, center: str = "", sub: str = "") -> go.Figure:
    n = len(labels)
    fig = go.Figure(go.Pie(labels=labels, values=values, hole=0.72, sort=False, marker=dict(colors=ramp(n), line=dict(color="#040404", width=3)),
                           textinfo="label+percent", textposition="outside", textfont=dict(size=12), hovertemplate="%{label}<br>%{value:,.0f}<extra></extra>"))
    base_layout(fig, title)
    fig.update_layout(margin=dict(l=40, r=40, t=60, b=30))
    if center:
        fig.add_annotation(text=center, x=0.5, y=0.54, xref="paper", yref="paper", showarrow=False, font=dict(size=32, color=LIME, family=FONT_STACK))
        fig.add_annotation(text=sub, x=0.5, y=0.43, xref="paper", yref="paper", showarrow=False, font=dict(size=11, color=MUTED, family=FONT_STACK))
    return fig


def lollipop_chart(labels, values, title: str, fmt: str = "{:.1f}", ytitle: str = "") -> go.Figure:
    vals = [float(v) for v in values]
    n = len(vals)
    fig = go.Figure(go.Scatter(x=[str(x) for x in labels], y=vals, mode="markers+text", text=[fmt.format(v) for v in vals], textposition="top center",
                               textfont=dict(size=12, color=MUTED), marker=dict(size=14, color=LIME, line=dict(color="#7CF2CC", width=1)),
                               error_y=dict(type="data", symmetric=False, array=[0] * n, arrayminus=vals, thickness=3, width=0, color="rgba(0,200,136,.3)"),
                               hovertemplate="%{x}<br><b>%{y:,.2f}</b><extra></extra>"))
    fig.update_yaxes(title=ytitle, range=[0, max(vals) * 1.2 if vals else 1])
    return base_layout(fig, title)


def radar_chart(cats, vals, title: str) -> go.Figure:
    cats, vals = list(cats), list(vals)
    fig = go.Figure(go.Scatterpolar(r=vals + vals[:1], theta=cats + cats[:1], fill="toself", mode="lines+markers", line=dict(color=LIME, width=2),
                                    marker=dict(size=8, color=WHITE), fillcolor="rgba(0,200,136,.12)", hovertemplate="%{theta}<br><b>%{r:,.1f}</b><extra></extra>"))
    base_layout(fig, title, 410)
    fig.update_layout(polar=dict(bgcolor="rgba(0,0,0,0)", radialaxis=dict(gridcolor=GRID, tickfont=dict(color=MUTED, size=11), range=[0, max(vals) * 1.15 if vals else 1]),
                                 angularaxis=dict(gridcolor=GRID, tickfont=dict(color=WHITE, size=12))), margin=dict(l=40, r=40, t=60, b=30))
    return fig


def scatter_trend(df: pd.DataFrame, x: str, y: str, title: str, xt: str, yt: str) -> go.Figure:
    z = df[[x, y]].replace([np.inf, -np.inf], np.nan).dropna()
    if len(z) > 5000:
        z = z.sample(5000, random_state=2)
    fig = go.Figure(go.Scattergl(x=z[x], y=z[y], mode="markers", marker=dict(color=LIME, size=6, opacity=.45),
                                 hovertemplate=f"{xt}: %{{x:,.1f}}<br>{yt}: %{{y:,.1f}}<extra></extra>"))
    if len(z) >= 3 and z[x].nunique() > 1:
        m, b = np.polyfit(z[x], z[y], 1)
        xx = np.linspace(z[x].min(), z[x].max(), 60)
        fig.add_trace(go.Scatter(x=xx, y=m * xx + b, mode="lines", line=dict(color=WHITE, width=1.4, dash="dot"), hoverinfo="skip", name="Trend"))
    fig.update_xaxes(title=xt)
    fig.update_yaxes(title=yt)
    return base_layout(fig, title)


def calendar_heat(df: pd.DataFrame) -> go.Figure:
    daily = df.groupby("Booking_Date").size()
    first = daily.index.min().replace(day=1)
    off = first.dayofweek
    Z = np.full((7, 6), np.nan)
    T = [[""] * 6 for _ in range(7)]
    for d, v in daily.items():
        w, r = (d.day - 1 + off) // 7, d.dayofweek
        if w < 6:
            Z[r][w], T[r][w] = v, str(d.day)
    fig = go.Figure(go.Heatmap(z=Z, x=[f"W{i + 1}" for i in range(6)], y=[x[:3] for x in DAYS], text=T, texttemplate="%{text}", textfont=dict(size=12, color=WHITE),
                               colorscale=LIME_SCALE, xgap=5, ygap=5, hoverongaps=False, showscale=False, hovertemplate="Day %{text}<br>%{z:,} bookings<extra></extra>"))
    base_layout(fig, f"Calendar / {first:%B %Y}", 410)
    fig.update_yaxes(autorange="reversed", showgrid=False)
    fig.update_xaxes(showgrid=False)
    return fig


def pareto_reasons(df: pd.DataFrame) -> go.Figure:
    r = df[df["Cancellation_Reason"].notna()]["Cancellation_Reason"].value_counts()
    p = pareto(r)
    x = [str(v)[:20] for v in p.iloc[:, 0]]
    fig = go.Figure()
    fig.add_trace(go.Bar(x=x, y=p["value"], marker=dict(color=p["value"], colorscale=[[0, "#04201A"], [1, LIME]]), name="Cancellations",
                         hovertemplate="%{x}<br>%{y:,}<extra></extra>"))
    fig.add_trace(go.Scatter(x=x, y=p["cum_share"] * 100, name="Cumulative %", yaxis="y2", mode="lines+markers", line=dict(color=WHITE, width=2),
                             marker=dict(size=8, color=WHITE, line=dict(color=LIME, width=2))))
    base_layout(fig, "Pareto / which reasons carry the loss", 410, legend=True)
    fig.update_layout(yaxis2=dict(overlaying="y", side="right", range=[0, 105], ticksuffix="%", showgrid=False, tickfont=dict(color=MUTED, size=11)))
    fig.update_xaxes(tickfont=dict(size=10), showgrid=False)
    return fig


def value_sankey(df: pd.DataFrame) -> go.Figure:
    v = df.groupby("Booking_Status")["Booking_Value"].sum()
    ok = df[df["Is_Success"]]
    comp = float(df.loc[df["Is_Completed_Ride"], "Booking_Value"].sum())
    inc = float(ok["Booking_Value"].sum()) - comp
    names = ["All bookings", "Successful", "Cancelled by customer", "Cancelled by driver", "No driver found", "Fully completed", "Incomplete"]
    cols = [LIME, "#00C888", "#9BF5D6", WHITE, "#01674E", "#7CF2CC", "#5E7A72"]
    src, dst = [0, 0, 0, 0, 1, 1], [1, 2, 3, 4, 5, 6]
    val = [float(v.get("Success", 0)), float(v.get("Canceled by Customer", 0)), float(v.get("Canceled by Driver", 0)), float(v.get("Driver Not Found", 0)), comp, inc]
    fig = go.Figure(go.Sankey(node=dict(label=names, color=cols, pad=18, thickness=16, line=dict(color="#040404", width=1)),
                              link=dict(source=src, target=dst, value=val, color=[hex_rgba(cols[d], 0.28) if cols[d].startswith("#") else "rgba(255,255,255,.2)" for d in dst])))
    return base_layout(fig, "Where booking value goes", 410)


def anomaly_scatter(df: pd.DataFrame) -> go.Figure:
    flag = df.groupby("Vehicle_Type")["Booking_Value"].transform(iqr_outliers)
    smp = df.sample(min(4000, len(df)), random_state=3)
    f = flag.loc[smp.index]
    jit = np.random.default_rng(1).uniform(-0.3, 0.3, len(smp))
    fig = go.Figure()
    fig.add_trace(go.Scattergl(x=smp.loc[~f, "Booking_Hour"] + jit[~f.values], y=smp.loc[~f, "Booking_Value"], mode="markers", name="Normal",
                               marker=dict(size=4, color="rgba(154,160,143,.35)"), hoverinfo="skip"))
    hit = smp[f]
    fig.add_trace(go.Scattergl(x=hit["Booking_Hour"], y=hit["Booking_Value"], mode="markers", name="Flagged",
                               marker=dict(size=9, color=LIME, line=dict(width=1.5, color=WHITE)), hovertemplate="%{x}:00<br>value %{y:,.0f}<extra></extra>"))
    fig.update_xaxes(title="hour of day")
    return base_layout(fig, "Anomaly radar / booking value by hour", 380, legend=True)


def quality_ring(score: float) -> go.Figure:
    fig = go.Figure(go.Pie(values=[score, max(100 - score, 0.0001)], hole=0.82, sort=False, textinfo="none", hoverinfo="skip",
                           marker=dict(colors=[LIME, "rgba(255,255,255,.06)"], line=dict(color="#040404", width=0))))
    base_layout(fig, "Quality score", 300)
    fig.add_annotation(text=f"{score:.2f}%", x=0.5, y=0.5, xref="paper", yref="paper", showarrow=False, font=dict(size=28, color=LIME, family=FONT_STACK))
    return fig


# ----------------------------------------------------------------------------- clickable mini charts
def mini(sp: dict):
    """Clickable chart ('lolli' or 'pill'). Returns the clicked label."""
    labels = [str(x) for x in sp["labels"]]
    vals = [float(v) for v in sp["values"]]
    n, horiz, kind = len(vals), sp.get("horizontal", False), sp.get("style", "pill")
    fmt, show, h = sp.get("fmt", "{:,.0f}"), sp.get("text", True), sp.get("h", 270)
    tx = [fmt.format(v) for v in vals] if show else None
    mx = max(vals) if vals else 1
    stem = dict(type="data", symmetric=False, thickness=3, width=0, color="rgba(0,200,136,.32)")
    mcol = sp.get("colors") or LIME
    fig = go.Figure()
    if kind == "lolli":
        mk = dict(size=13, color=mcol, line=dict(color=WHITE, width=1.5))
        if horiz:
            fig.add_trace(go.Scatter(x=vals, y=labels, mode="markers+text" if show else "markers", text=tx, textposition="middle right", textfont=dict(size=12, color=MUTED),
                                     error_x=dict(array=[0] * n, arrayminus=vals, **stem), marker=mk, hovertemplate="%{y}<br>%{x:,.4g}<extra></extra>"))
        else:
            fig.add_trace(go.Scatter(x=labels, y=vals, mode="markers+text" if show else "markers", text=tx, textposition="top center", textfont=dict(size=12, color=MUTED),
                                     error_y=dict(array=[0] * n, arrayminus=vals, **stem), marker=mk, hovertemplate="%{x}<br>%{y:,.4g}<extra></extra>"))
        fig.update_traces(selected=dict(marker=dict(opacity=1)), unselected=dict(marker=dict(opacity=0.3)))
    else:
        marker = dict(color=sp["colors"]) if sp.get("colors") else dict(color=vals, colorscale=[[0, "#04201A"], [0.5, "#00A06E"], [1, LIME]], cmin=0, cmax=mx)
        if horiz:
            fig.add_trace(go.Bar(y=labels, x=vals, orientation="h", marker=marker, text=tx, textposition="outside", textfont=dict(size=12, color=MUTED),
                                 hovertemplate="%{y}<br>%{x:,.4g}<extra></extra>"))
        else:
            fig.add_trace(go.Bar(x=labels, y=vals, marker=marker, text=tx, textposition="outside", textfont=dict(size=12, color=MUTED),
                                 hovertemplate="%{x}<br>%{y:,.4g}<extra></extra>"))
        fig.update_traces(selected=dict(marker=dict(opacity=1)), unselected=dict(marker=dict(opacity=0.3)), cliponaxis=False)
        try:
            fig.update_layout(barcornerradius=8)
        except ValueError:
            pass
    fig.update_layout(clickmode="event+select", dragmode=False, bargap=0.3)
    base_layout(fig, sp["title"] + "  /  click", h)
    if horiz:
        fig.update_yaxes(autorange="reversed", showgrid=False)
        fig.update_xaxes(showgrid=False, showticklabels=False, range=[0, mx * 1.3])
    else:
        fig.update_yaxes(showticklabels=False, range=[0, mx * 1.22])
        fig.update_xaxes(showgrid=False)
        if sp.get("short"):
            fig.update_xaxes(tickmode="array", tickvals=labels, ticktext=sp["short"])
    ev = plot(fig, sp["key"], select=True)
    try:
        pts = ev["selection"]["points"]
    except Exception:
        pts = []
    if pts:
        idx = pts[0].get("point_index", pts[0].get("point_number"))
        if idx is not None and 0 <= int(idx) < len(labels):
            return labels[int(idx)]
    return None


def specs_command(df):
    s = df["Booking_Status"].value_counts().reindex(STATUS_ORDER).dropna()
    v = df["Vehicle_Type"].value_counts()
    p = df[df["Is_Success"]].groupby("Payment_Method")["Booking_Value"].sum().sort_values(ascending=False)
    hh = df.groupby("Booking_Hour").size()
    return [dict(key="m_status", kind="status", title="Outcome", labels=s.index, values=s.values, style="lolli", horizontal=True, colors=[STATUS_COL[i] for i in s.index]),
            dict(key="m_veh", kind="vehicle", title="Vehicle volume", labels=v.index, values=v.values, text=False, short=[x[:6] for x in v.index]),
            dict(key="m_pay", kind="payment", title="Value by payment M", labels=p.index, values=p.values / 1e6, style="lolli", fmt="{:.1f}"),
            dict(key="m_hour", kind="hour", title="Bookings by hour", labels=hh.index, values=hh.values, text=False)]


def right_command(df):
    m = hour_dow_matrix(df).reindex(range(24), fill_value=0)
    rotating(bars3d(m))
    note("Hour by weekday, raw counts. Drag to rotate, or switch on Hand control (bottom) and use your palm; hover pauses the spin. Mon-Wed look taller only because July 2024 has five of each.")
    v, cols, shows = m.values.astype(float), list(m.columns), []
    if v.size and v.max() > 0:
        r, c = np.unravel_index(v.argmax(), v.shape)
        shows.append(f"Busiest slot: **{cols[c]} {r:02d}:00** with **{int(v[r, c]):,}** bookings (the amber marker on the chart).")
        pos = np.where(v > 0, v, np.nan)
        if np.isfinite(pos).any():
            lo = np.nanmin(pos)
            rq, cq = np.unravel_index(np.nanargmin(pos), v.shape)
            shows.append(f"Quietest slot with any demand: {cols[cq]} {rq:02d}:00 with **{int(lo):,}**. The busiest block is **{v[r, c] / lo:.1f}x** that.")
        hr = v.sum(axis=1)
        shows.append(f"Across the whole week the busiest hour of the day is **{int(hr.argmax()):02d}:00** ({int(hr.max()):,} bookings).")
    read_card(["Each block is one hour of one weekday. Left to right is Monday to Sunday, front to back is the hour, 00 to 23.",
               "Height and brightness both show bookings: taller and brighter means busier.",
               "Press **TOP** to look straight down from above: the brightest squares are the busiest slots."], shows)


def specs_demand(df):
    w = per_weekday_average(df)
    t = df.groupby("Time_Of_Day").size().reindex(TOD).dropna()
    hh = df.groupby("Booking_Hour").size()
    return [dict(key="d_wd", kind="weekday", title="Avg bookings per weekday", labels=w["Day_Name"], values=w["avg_bookings_per_day"], short=[d[:3] for d in w["Day_Name"]]),
            dict(key="d_tod", kind="tod", title="Time of day", labels=t.index, values=t.values, style="lolli", short=[x[:5] for x in t.index]),
            dict(key="d_hr", kind="hour", title="Hour of day", labels=hh.index, values=hh.values, text=False)]


def right_demand(df):
    rotating(terrain3d(df), speed=0.004)
    note("Demand terrain: hour of day against day of month. A flat surface means no strong peak.")
    m = df.pivot_table(index="Booking_Hour", columns="Day", values="Booking_ID", aggfunc="count", fill_value=0).reindex(range(24), fill_value=0)
    v, shows = m.values.astype(float), []
    if v.size and v.max() > 0:
        h, d = np.unravel_index(v.argmax(), v.shape)
        shows.append(f"Highest point: day **{m.columns[d]}** at **{h:02d}:00** with **{int(v[h, d]):,}** bookings (the amber marker).")
        day = v.sum(axis=0)
        shows.append(f"Busiest day of the month: **day {m.columns[int(day.argmax())]}** ({int(day.max()):,}). Quietest: day {m.columns[int(day.argmin())]} ({int(day.min()):,}).")
        ratio = v.max() / max(v.mean(), 1e-9)
        shows.append(f"The highest point is **{ratio:.1f}x** the average hour-day. " + ("That is a fairly flat surface: demand is steady." if ratio < 1.6 else "That is a clearly peaked surface."))
    read_card(["Left to right is the day of the month, front to back is the hour of the day.",
               "Height is bookings. A hill is a busy moment, a valley a quiet one.",
               "A flat sheet means no strong peak. Press **TOP** to look down on it like a colour map, **FRONT** to judge heights."], shows)


def specs_fleet(df):
    sc = vehicle_scorecard(df)
    sh = [x[:6] for x in sc["Vehicle_Type"]]
    return [dict(key="f_vol", kind="vehicle", title="Bookings", labels=sc["Vehicle_Type"], values=sc["total_bookings"], text=False, short=sh),
            dict(key="f_sr", kind="vehicle", title="Success rate %", labels=sc["Vehicle_Type"], values=sc["success_rate"] * 100, style="lolli", fmt="{:.1f}", short=sh),
            dict(key="f_dist", kind="vehicle", title="Avg distance km", labels=sc["Vehicle_Type"], values=sc["avg_distance"], style="lolli", fmt="{:.1f}", short=sh)]


def right_fleet(df):
    sc = vehicle_scorecard(df)
    rotating(bubble3d(sc), speed=0.005)
    note("Each bubble is a vehicle: distance, success rate and customer rating. Size is bookings.")
    shows = []
    if len(sc):
        big, best = sc.loc[sc["total_bookings"].idxmax()], sc.loc[sc["success_rate"].idxmax()]
        far, top = sc.loc[sc["avg_distance"].idxmax()], sc.loc[sc["avg_customer_rating"].idxmax()]
        gap = (sc["success_rate"].max() - sc["success_rate"].min()) * 100
        shows += [f"Biggest bubble: **{big['Vehicle_Type']}** with **{int(big['total_bookings']):,}** bookings.",
                  f"Highest success rate: **{best['Vehicle_Type']}** at **{best['success_rate']:.1%}**. Longest average ride: **{far['Vehicle_Type']}** at {far['avg_distance']:.1f} km. Best customer rating: **{top['Vehicle_Type']}** ({top['avg_customer_rating']:.2f}).",
                  f"Best and worst success rate are only **{gap:.1f} points** apart. " + ("Treat that ranking cautiously." if gap < 2 else "That is a real gap.")]
    read_card(["Each bubble is one vehicle type. A bigger bubble means more bookings.",
               "Right is a longer average ride, further back is a higher success rate, higher up is a better customer rating.",
               "Press **TOP** to compare distance against success rate, **FRONT** to compare distance against rating."], shows)


def specs_cancel(df):
    r = df[df["Cancellation_Reason"].notna()]["Cancellation_Reason"].value_counts()
    vr = vehicle_scorecard(df).sort_values("cancellation_rate", ascending=False)
    hh = df[~df["Is_Success"]].groupby("Booking_Hour").size()
    return [dict(key="c_reason", kind="reason", title="Reasons", labels=r.index, values=r.values, style="lolli", horizontal=True, h=300),
            dict(key="c_veh", kind="vehicle", title="Cancel rate % by vehicle", labels=vr["Vehicle_Type"], values=vr["cancellation_rate"] * 100, fmt="{:.1f}", h=300, short=[x[:6] for x in vr["Vehicle_Type"]]),
            dict(key="c_hour", kind="hour", title="Failed bookings by hour", labels=hh.index, values=hh.values, text=False, h=300)]


def right_cancel(df):
    rotating(status_terrain3d(df), speed=0.004)
    note("Bookings per status per day. Drag to rotate.")
    m, shows = pd.crosstab(df["Booking_Status"], df["Day"]), []
    failed = m.drop(index="Success", errors="ignore")
    if failed.size:
        fd = failed.sum(axis=0)
        shows.append(f"Worst day for failed bookings: **day {int(fd.idxmax())}** with **{int(fd.max()):,}**. Best day: day {int(fd.idxmin())} with {int(fd.min()):,}.")
        cu = int(m.loc["Canceled by Customer"].sum()) if "Canceled by Customer" in m.index else 0
        dr = int(m.loc["Canceled by Driver"].sum()) if "Canceled by Driver" in m.index else 0
        if cu and dr:
            shows.append(f"Driver cancellations (**{dr:,}**) against customer cancellations (**{cu:,}**): **{dr / cu:.1f}x**.")
    shows.append("Success is the tall ridge every day, so compare the lower ridges with each other, not with it.")
    read_card(["Each row is one booking outcome. Left to right is the day of the month, height is how many bookings that day.",
               "Success is the big ridge; the smaller ridges are the different ways a booking can fail.",
               "Press **FRONT** to follow the day-by-day pattern, **SIDE** to line the outcomes up against each other."], shows)


def specs_revenue(df):
    ok = df[df["Is_Success"]]
    p = ok.groupby("Payment_Method")["Booking_Value"].sum().sort_values(ascending=False)
    vv = ok.groupby("Vehicle_Type")["Booking_Value"].sum().sort_values(ascending=False)
    t = ok.groupby("Time_Of_Day")["Booking_Value"].sum().reindex(TOD).dropna()
    return [dict(key="r_pay", kind="payment", title="Value by payment M", labels=p.index, values=p.values / 1e6, style="lolli", fmt="{:.1f}"),
            dict(key="r_veh", kind="vehicle", title="Value by vehicle M", labels=vv.index, values=vv.values / 1e6, fmt="{:.1f}", short=[x[:6] for x in vv.index]),
            dict(key="r_tod", kind="tod", title="Value by time of day M", labels=t.index, values=t.values / 1e6, style="lolli", fmt="{:.1f}", short=[x[:5] for x in t.index])]


def right_revenue(df):
    ok = df[df["Is_Success"]]
    rotating(scatter3d(ok), speed=0.0035)
    note(f"Sample of 2,500 rides. Correlation of booking value with distance is {ok['Booking_Value'].corr(ok['Ride_Distance']):.2f}, unusually weak for fares and worth flagging.")
    shows = []
    if len(ok):
        q = ok["Customer_Rating"].quantile([0.1, 0.9])
        corr = ok["Booking_Value"].corr(ok["Ride_Distance"])
        shows.append(f"A typical ride is about **{ok['Ride_Distance'].median():.1f} km** with a booking value of **{ok['Booking_Value'].median():,.0f}** (medians).")
        shows.append(f"Most ratings sit between **{q[0.1]:.1f}** and **{q[0.9]:.1f}** (the middle 80 percent of rides).")
        if pd.notna(corr):
            shows.append(f"Distance and booking value correlate at **{corr:.2f}**. A value of 1 would be a clean rising line of dots, 0 a shapeless cloud.")
    read_card(["Each dot is one completed ride (a sample of 2,500). The colour is the vehicle type.",
               "Left to right is distance, front to back is booking value, height is the customer rating.",
               "A rising line of dots means longer rides cost more; a shapeless cloud means they do not. Press **TOP** to see distance against value."], shows)


BUILDERS = {"Command Centre": (specs_command, right_command), "Demand Pulse": (specs_demand, right_demand), "Fleet": (specs_fleet, right_fleet),
            "Cancellations": (specs_cancel, right_cancel), "Revenue & Riders": (specs_revenue, right_revenue)}


def quick_pick(page: str, specs: list, sel):
    """Fallback for the mini-chart clicks: the same insight, chosen from a dropdown."""
    ss = st.session_state
    default = "Or pick from a list"
    items: dict = {default: None}
    for sp in specs:
        for lab in sp["labels"]:
            lab = str(lab)
            shown = f"{int(lab):02d}:00" if sp["kind"] == "hour" else lab
            items[f"{sp['title']}  /  {shown}"] = (sp["kind"], lab)
    key = f"qp_{page}"
    choice = st.selectbox("Quick pick", list(items), key=key, label_visibility="collapsed")
    if choice != ss.get(key + "_seen", default):
        ss[key + "_seen"] = choice
        if items.get(choice):
            ss["last_click"] = (page,) + tuple(items[choice])
            return items[choice]
    return sel


@st.fragment
def interactive(page: str, df: pd.DataFrame) -> None:
    """Clickable charts + insight panel + 3D chart. Fragment: a click reruns only this block."""
    specs_fn, right_fn = BUILDERS[page]
    specs = specs_fn(df)
    clicks: dict = {}
    for col, sp in zip(st.columns(len(specs)), specs):
        with col:
            with st.container(border=True):
                lab = mini(sp)
            clicks[sp["key"]] = (sp["kind"], lab) if lab else None
    sel = pick_click(page, clicks)
    left, right = st.columns([5, 7])
    with left:
        sel = quick_pick(page, specs, sel)
        insight_panel(insight(sel[0], sel[1], df) if sel else None)
    with right:
        right_fn(df)


