def page_demand(df, k, sc):
    hero("Demand Pulse", "Hours, weekdays and days of the month, from the raw rhythm to a 3D terrain.")
    hh = df.groupby("Booking_Hour").size()
    daily = df.groupby("Booking_Date").size()
    wk = df.groupby("Is_Weekend").size()
    share = wk.get(True, 0) / max(wk.sum(), 1)
    kpi_row([("Busiest hour", f"{int(hh.idxmax()):02d}:00", f"{fmt_in(hh.max())} bookings", None), ("Quietest hour", f"{int(hh.idxmin()):02d}:00", f"{fmt_in(hh.min())} bookings", None),
             ("Busiest day", f"{daily.idxmax():%d %b}", f"{fmt_in(daily.max())} bookings", None), ("Weekend share", f"{share:.1%}", "of all bookings", (share * 100, 1, "%"))])
    section("00", "LIVE SIGNALS", "The signals behind the numbers")
    interactive("Demand Pulse", df)
    section("01", "HOURLY BEHAVIOUR", "When demand tends to happen")
    a, b = st.columns(2)
    hourly = hh.rename("Bookings").reset_index()
    sr = (df.groupby("Booking_Hour")["Is_Success"].mean() * 100).rename("Success").reset_index()
    with a:
        chart(neon_peak_chart(hourly, "Booking_Hour", "Bookings", "Bookings by hour", "Bookings"), "dm_hour", "Hourly bookings", peak_text(hourly, "Booking_Hour", "Bookings", "bookings", xf=hh_xf))
    with b:
        chart(pulse_chart(sr, "Booking_Hour", "Success", "Success rate by hour", "Success %"), "dm_sr", "Success by hour",
              f"Success rate stays between <b>{sr['Success'].min():.1f}%</b> and <b>{sr['Success'].max():.1f}%</b> across the day, a spread of only <b>{sr['Success'].max() - sr['Success'].min():.1f} points</b>.")
    section("02", "WEEK STRUCTURE", "Weekday and calendar comparison")
    a, b = st.columns(2)
    w = per_weekday_average(df)
    top = w.loc[w["avg_bookings_per_day"].idxmax()]
    with a:
        chart(radar_chart(w["Day_Name"], w["avg_bookings_per_day"].round(1), "Weekday radar / avg bookings per day"), "dm_radar", "Weekday radar",
              f"<b>{top['Day_Name']}</b> is the busiest weekday at <b>{top['avg_bookings_per_day']:,.0f}</b> bookings per day. Averages remove the five-versus-four weekday count bias.")
    with b:
        chart(calendar_heat(df), "dm_cal", "Calendar", "Brighter cells are busier days. Day-to-day variation is modest.")


def page_fleet(df, k, sc):
    hero("Fleet", "Volume, success, distance and ratings across vehicle types. Bars start at zero on purpose, so small gaps look as small as they are.")
    best, big, rated = sc.sort_values("success_rate").iloc[-1], sc.iloc[0], sc.sort_values("avg_customer_rating").iloc[-1]
    kpi_row([("Vehicle types", str(len(sc)), "in this selection", (len(sc), 0, "")), ("Highest volume", str(big["Vehicle_Type"]), f"{fmt_in(big['total_bookings'])} bookings", None),
             ("Best success rate", str(best["Vehicle_Type"]), f"{best['success_rate']:.1%}", None), ("Best rated", str(rated["Vehicle_Type"]), f"{rated['avg_customer_rating']:.2f} customer rating", None)])
    section("00", "LIVE SIGNALS", "The signals behind the numbers")
    interactive("Fleet", df)
    section("01", "PERFORMANCE", "How each vehicle type performs")
    a, b = st.columns(2)
    with a:
        chart(composition_chart(sc["Vehicle_Type"], sc["total_bookings"], "Share of bookings"), "fl_comp", "Booking share",
              f"<b>{big['Vehicle_Type']}</b> leads with <b>{big['total_bookings'] / sc['total_bookings'].sum():.1%}</b> of bookings; the spread across types is narrow.")
    with b:
        gap = (best["success_rate"] - sc["success_rate"].min()) * 100
        chart(lollipop_chart(sc["Vehicle_Type"], sc["success_rate"] * 100, "Success rate by vehicle", "{:.1f}", "Success %"), "fl_sr", "Success rate",
              f"<b>{best['Vehicle_Type']}</b> is highest at <b>{best['success_rate']:.1%}</b>. Best to worst is only <b>{gap:.2f} points</b>, so treat the ranking cautiously.")
    section("02", "RELATIONSHIPS", "Distance, fare and rating")
    a, b = st.columns(2)
    ok = df[df["Is_Success"]]
    with a:
        chart(scatter_trend(ok, "Ride_Distance", "Booking_Value", "Distance vs booking value", "Distance km", "Booking value"), "fl_sc", "Distance and value",
              corr_text(ok, "Ride_Distance", "Booking_Value", "distance", "booking value"))
    with b:
        chart(lollipop_chart(sc["Vehicle_Type"], sc["avg_customer_rating"], "Average customer rating", "{:.2f}", "Rating"), "fl_rt", "Ratings",
              f"<b>{rated['Vehicle_Type']}</b> is rated highest at <b>{rated['avg_customer_rating']:.2f}</b>. Ratings exist only for successful rides.")
    section("03", "SCORECARD", "Every metric in one table")
    d = sc[["Vehicle_Type", "total_bookings", "success_rate", "cancellation_rate", "avg_distance", "avg_customer_rating", "avg_driver_rating", "total_value"]].copy()
    d.columns = ["Vehicle", "Bookings", "Success %", "Cancelled %", "Avg km", "Cust rating", "Drv rating", "Booking value"]
    d[["Success %", "Cancelled %"]] = (d[["Success %", "Cancelled %"]] * 100).round(1)
    st.markdown(html_table(d.round(2), {"Bookings": (d["Bookings"].max(), LIME), "Success %": (100, LIME), "Cancelled %": (100, WHITE), "Booking value": (d["Booking value"].max(), LIME)}), unsafe_allow_html=True)


def page_cancel(df, k, sc):
    hero("Cancellations", f"{fmt_in(k['driver_cancellations'])} driver cancels, {fmt_in(k['customer_cancellations'])} customer cancels and {fmt_in(k['driver_not_found'])} bookings with no driver found.")
    lost = df[~df["Is_Success"]]["Booking_Value"].sum()
    kpi_row([("Driver cancels", fmt_in(k["driver_cancellations"]), "by the driver", (k["driver_cancellations"], 0, "")), ("Customer cancels", fmt_in(k["customer_cancellations"]), "by the rider", (k["customer_cancellations"], 0, "")),
             ("No driver found", fmt_in(k["driver_not_found"]), f"{k['driver_not_found_rate']:.1%} of bookings", (k["driver_not_found"], 0, "")),
             ("Booking value lost", short_in(lost)[0], "intended fares, not revenue", (short_in(lost)[1], short_in(lost)[2], short_in(lost)[3]))])
    section("00", "LIVE SIGNALS", "The signals behind the numbers")
    interactive("Cancellations", df)
    section("01", "WHY BOOKINGS FAIL", "Reasons and who raises them")
    a, b = st.columns([7, 5])
    r = df[df["Cancellation_Reason"].notna()]["Cancellation_Reason"].value_counts()
    cat = df["Cancellation_Category"].dropna().value_counts()
    with a:
        chart(pareto_reasons(df), "cn_pareto", "Cancellation reasons",
              f"<b>{r.index[0]}</b> is the top recorded reason with <b>{r.iloc[0]:,}</b> cancellations (<b>{r.iloc[0] / r.sum():.1%}</b>). Reasons are self-reported labels, not proven causes." if len(r) else "No recorded reasons.")
    with b:
        chart(donut(list(cat.index), list(cat.values), "Who ends the booking", f"{cat.iloc[0] / cat.sum():.0%}", str(cat.index[0]).upper()), "cn_cat", "Who cancels",
              f"<b>{cat.index[0]}</b> accounts for <b>{cat.iloc[0] / cat.sum():.1%}</b> of failed bookings." if len(cat) else "No failed bookings.")
    section("02", "WHEN AND WHERE", "Failure rate by hour and vehicle")
    a, b = st.columns(2)
    fh = ((1 - df.groupby("Booking_Hour")["Is_Success"].mean()) * 100).rename("Fail").reset_index()
    sc2 = sc.assign(fail=(1 - sc["success_rate"]) * 100)
    worst = sc2.loc[sc2["fail"].idxmax()]
    with a:
        chart(neon_peak_chart(fh, "Booking_Hour", "Fail", "Failed share by hour", "Failed %"), "cn_hour", "Failure by hour", peak_text(fh, "Booking_Hour", "Fail", "failed", "%", xf=hh_xf, yf="{:,.1f}"))
    with b:
        chart(lollipop_chart(sc2["Vehicle_Type"], sc2["fail"], "Failed share by vehicle", "{:.1f}", "Failed %"), "cn_veh", "Failure by vehicle",
              f"<b>{worst['Vehicle_Type']}</b> has the highest failed share at <b>{worst['fail']:.1f}%</b>. Differences between vehicles are small.")


def page_revenue(df, k, sc):
    hero("Revenue & Riders", "Booking value is the intended fare, not revenue. The flow below shows how much of it survives to a fully completed ride.")
    t, s, f = short_in(k["total_booking_value"]), short_in(k["successful_booking_value"]), short_in(k["fully_completed_value"])
    kpi_row([("All booking value", t[0], "intended fares", (t[1], t[2], t[3])), ("Successful value", s[0], "status = Success", (s[1], s[2], s[3])),
             ("Fully completed", f[0], "success and not incomplete", (f[1], f[2], f[3])), ("Avg booking value", fmt_in(k["avg_booking_value"]), "per booking", (k["avg_booking_value"], 0, ""))])
    section("00", "LIVE SIGNALS", "The signals behind the numbers")
    interactive("Revenue & Riders", df)
    ok = df[df["Is_Success"]]
    section("01", "VALUE FLOW", "From booking to completed ride")
    a, b = st.columns([7, 5])
    band = df["Revenue_Category"].dropna().value_counts()
    with a:
        chart(value_sankey(df), "rv_sankey", "Value flow", f"<b>{(k['successful_booking_value'] / k['total_booking_value']):.1%}</b> of intended booking value reaches a successful ride and <b>{(k['fully_completed_value'] / k['total_booking_value']):.1%}</b> a fully completed one.")
    with b:
        chart(donut(list(band.index), list(band.values), "Bookings by value band", f"{band.iloc[0] / band.sum():.0%}", str(band.index[0]).split(" ")[0].upper()), "rv_band", "Value bands",
              f"The largest band is <b>{band.index[0]}</b> with <b>{band.iloc[0] / band.sum():.1%}</b> of bookings.")
    section("02", "FARE AND RATINGS", "Does fare follow distance, do ratings agree")
    a, b = st.columns(2)
    with a:
        chart(scatter_trend(ok, "Ride_Distance", "Booking_Value", "Distance vs booking value", "Distance km", "Booking value"), "rv_sc", "Fare and distance", corr_text(ok, "Ride_Distance", "Booking_Value", "distance", "booking value"))
    with b:
        chart(scatter_trend(ok, "Customer_Rating", "Driver_Rating", "Customer vs driver rating", "Customer rating", "Driver rating"), "rv_rt", "Rating agreement", corr_text(ok, "Customer_Rating", "Driver_Rating", "customer rating", "driver rating"))
    section("03", "RIDERS", "Loyalty and top customers")
    a, b = st.columns([5, 7])
    per = df["Customer_ID"].value_counts()
    one, rep = int((per == 1).sum()), int((per > 1).sum())
    with a:
        chart(donut(["One booking", "Repeat riders"], [one, rep], "Rider loyalty", f"{rep / max(one + rep, 1):.0%}", "REPEAT"), "rv_loyal", "Loyalty", f"<b>{rep:,}</b> of <b>{one + rep:,}</b> customers booked more than once.")
    with b:
        top = df.groupby("Customer_ID").agg(Bookings=("Booking_ID", "size"), Value=("Booking_Value", "sum")).nlargest(9, "Value").reset_index()
        with st.container(border=True):
            st.markdown('<div class="kick" style="margin:6px 0 10px">TOP CUSTOMERS BY BOOKING VALUE</div>', unsafe_allow_html=True)
            st.markdown(html_table(top, {"Value": (top["Value"].max(), LIME)}), unsafe_allow_html=True)


def page_data(df, k, sc):
    hero("Data Room", "Anomaly flags, a data-quality audit, the raw table and project notes. For questions about any page, use the AI button at the bottom right.")
    t2, t3, t4, t5 = st.tabs(["Anomaly radar", "Data quality", "Explorer", "About"])
    with t2:
        note("A flag is a statistical outlier, not evidence of fraud.")
        chart(anomaly_scatter(df), "lab_anom", "Anomaly radar", "Highlighted points are booking values outside the IQR fence for their vehicle type.")
        for a in detect(df):
            sev = {"High": "hi", "Medium": "mid", "Low": "lo"}[a["severity"]]
            st.markdown(f'<div class="card"><h4>{html.escape(a["title"]).upper()}</h4><span class="tag {sev}">{a["severity"].upper()}</span><span class="tag">{fmt_in(a["count"])} FLAGGED</span>'
                        f'<span class="tag">{a["share"]:.1%}</span><p>{html.escape(a["method"])}. {html.escape(a["limitation"])}</p></div>', unsafe_allow_html=True)
            rec = a["records"]
            keep = [c for c in ["Booking_ID", "Vehicle_Type", "Booking_Value", "Ride_Distance", "value_per_km", "Booking_Date", "z_score"] if c in rec.columns]
            with st.expander("Show records"):
                st.markdown(html_table(rec[keep], max_rows=25), unsafe_allow_html=True)
    with t3:
        au = load_audit()
        a, b = st.columns([4, 6])
        with a:
            with st.container(border=True):
                plot(quality_ring(float(au["data_quality_score"])), "lab_ring")
            st.caption(au["data_quality_formula"])
        with b:
            rules = ["duplicate_booking_ids", "invalid_rating_count", "nonpositive_booking_value", "negative_distance", "success_with_zero_distance",
                     "nonsuccess_with_distance", "nonsuccess_with_rating", "status_vs_reason_inconsistent", "timestamp_time_mismatch"]
            st.markdown('<div class="checks">' + "".join(
                f'<div class="c {"ok" if au.get(r, 0) == 0 else "bad"}"><span>{html.escape(r.replace("_", " ")).upper()}</span><b>{"PASS" if au.get(r, 0) == 0 else fmt_in(au[r])}</b></div>' for r in rules) + "</div>", unsafe_allow_html=True)
        note(au["note_structural_missing"])
    with t4:
        show = st.multiselect("Columns", list(df.columns), default=["Booking_ID", "Timestamp", "Vehicle_Type", "Booking_Status", "Booking_Value", "Ride_Distance", "Payment_Method"])
        st.markdown(html_table(df[show] if show else df, max_rows=150), unsafe_allow_html=True)
        note(f"Showing the first 150 of {fmt_in(len(df))} rows. The download has all of them.")
        st.download_button("Download filtered CSV", df.to_csv(index=False).encode(), "ola_filtered.csv", "text/csv")
    with t5:
        note("July 2024 OLA bookings, 103,024 rows. Only the July sheet is raw; Sheet1 and Sheet2 are a pivot and an icon lookup.")
        st.markdown(logos(26), unsafe_allow_html=True)
        note("Typeface: Space Grotesk Medium, embedded in app.py (SIL Open Font License).")


