def reset_filters(dmin, dmax) -> None:
    st.session_state.update({"f_date": (dmin, dmax), "f_veh": [], "f_stat": [], "f_pay": [], "f_cq": "", "f_bq": ""})


def main() -> None:
    if not st.session_state.get("entered") and st.query_params.get("view") != "app":
        show_intro()
    st.markdown(CSS.replace("__FONT__", font_b64()).replace("__CUR__", CURSOR_URL), unsafe_allow_html=True)
    inject_js(COUNT_JS, "ola-count-js")
    inject_js(AI_JS, "ola-ai-js")
    inject_js(GESTURE_JS, "ola-gesture-js")
    df_all = get_data()
    dmin, dmax = df_all["Booking_Date"].min().date(), df_all["Booking_Date"].max().date()

    h1, h2 = st.columns([2, 9], vertical_alignment="center")
    h1.markdown('<div class="brand"><div class="mark"></div><div><div class="w">OLA</div><div class="s">MOBILITY INTELLIGENCE</div></div></div>', unsafe_allow_html=True)
    page = h2.radio("Navigate", PAGES, horizontal=True, label_visibility="collapsed", key="page")
    with st.expander("Filter data"):
        c1, c2, c3, c4 = st.columns(4)
        rng = c1.date_input("Date range", value=(dmin, dmax), min_value=dmin, max_value=dmax, key="f_date")
        veh = c2.multiselect("Vehicle", sorted(df_all["Vehicle_Type"].dropna().unique()), key="f_veh")
        stt = c3.multiselect("Status", sorted(df_all["Booking_Status"].dropna().unique()), key="f_stat")
        pay = c4.multiselect("Payment", sorted(df_all["Payment_Method"].dropna().unique()), key="f_pay")
        c5, c6, c7 = st.columns([2, 2, 1])
        cq = c5.text_input("Customer ID contains", key="f_cq")
        bq = c6.text_input("Booking ID contains", key="f_bq")
        c7.button("Reset filters", on_click=reset_filters, args=(dmin, dmax))
    d0, d1 = (rng[0], rng[1]) if isinstance(rng, (tuple, list)) and len(rng) == 2 else (dmin, dmax)
    fs = FilterState(pd.Timestamp(d0), pd.Timestamp(d1), veh, stt, pay, cq, bq)
    df = apply_filters(df_all, fs)
    if df.empty:
        st.warning("No bookings match these filters. Open Filter data and press Reset.")
        st.stop()
    k, sc = calc(repr(fs), df)
    if fs.active_count(df_all["Booking_Date"].min(), df_all["Booking_Date"].max()):
        st.markdown('<div class="chips">' + "".join(f"<span>{html.escape(c)}</span>" for c in fs.summary()) + "</div>", unsafe_allow_html=True)
    slug = "".join(ch for ch in page.lower() if ch.isalnum())
    try:
        box = st.container(key="pg_" + slug)
    except TypeError:
        box = st.container()
    with box:
        PAGE_FN[page](df, k, sc)
    st.markdown(f'<div class="foot"><span>OLA MOBILITY INTELLIGENCE / JULY 2024 INTERNSHIP PROJECT</span>{logos(18)}</div>', unsafe_allow_html=True)
    assistant(page, df, k, sc)


main()